using System.Collections.Generic;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceActionLogicsList", menuName = "Data/Battle/Logics/Dice Action/DiceActionLogicsList")]
public class DiceActionLogicsList : ScriptableObject
{
	public enum DiceActionLogicEnum
	{
		DiceActionLogic_AllCompanions,
		DiceActionLogic_AllCompanionsFainted,
		DiceActionLogic_AllEnemies,
		DiceActionLogic_AllTargets,
		DiceActionLogic_ChooseCompanion,
		DiceActionLogic_ChooseCompanionAliveOrFainted,
		DiceActionLogic_ChooseCompanionFainted,
		DiceActionLogic_ChooseDice,
		DiceActionLogic_ChooseEnemy,
		DiceActionLogic_ChooseEnemyDice,
		DiceActionLogic_ChoosePlayer,
		DiceActionLogic_ChoosePlayerDice,
		DiceActionLogic_ChooseSelfTarget,
		DiceActionLogic_ChooseTarget,
		DiceActionLogic_NoTarget,
		DiceActionLogic_RandomCompanion,
		DiceActionLogic_RandomCompanionXTimes,
		DiceActionLogic_RandomEnemy,
		DiceActionLogic_RandomEnemyXTimes,
		DiceActionLogic_RandomTarget,
		DiceActionLogic_RandomTargetXTimes
	}

	[Header("Battle Actions")]
	public List<DiceActionLogic> diceActionLogics = new List<DiceActionLogic>();

	public DiceActionLogic GetDiceActionLogic(DiceActionLogicEnum diceActionLogicEnum)
	{
		string text = diceActionLogicEnum.ToString();
		for (int i = 0; i < diceActionLogics.Count; i++)
		{
			if (text == diceActionLogics[i].name)
			{
				return diceActionLogics[i];
			}
		}
		return null;
	}
}
